/** Three simultaneous, interactive views of the same browser workspace. */
export function renderWall({store, archive, icon, esc, fmt, jobProgress, focus='all', immersive=false, receipt=null,decision=null}) {
  const state=store.state, project=store.getProject()||state.projects[0];
  const active=state.jobs.filter(j=>j.status==='running'&&jobProgress(j)<100).length;
  const current=id=>state.jobs.find(j=>j.machine===id&&j.status==='running'&&jobProgress(j)<100)||state.jobs.find(j=>j.machine===id&&j.status==='paused')||state.jobs.find(j=>j.machine===id&&j.status==='queued');
  const count=state.machines.length;
  const screens=[['atelier','01','La matière en action.','Parc, pièces et préparation'],['pilotage','02','Jarvis mène la création.','Intentions, missions et administration'],['creation','03','Le geste devient œuvre.','Œuvres, modèles 3D et vidéo']];
  const monitorHeader=(id,num,title,sub)=>`<header class="monitor-head"><span class="monitor-id">${num}</span><div><h2>${title}</h2><span>${sub}</span></div><button class="monitor-expand" data-screen="${id}" aria-label="Agrandir l’écran ${title}">${icon('arrowUp')}</button></header>`;
  return `<section class="panorama-head reveal"><div><p class="eyebrow">BOJ.ART / LE POSTE CENTRAL</p><h1>JARVIS. <em>AUX COMMANDES.</em></h1><p class="panorama-intro">La tour de contrôle BOJ.ART. De l’intention à la fabrication.</p></div><div class="panorama-actions"><button class="button" data-action="screens">${icon('screens')} Installer les 3 écrans</button><button class="button button-red" data-action="immersive" aria-pressed="${immersive}">${icon('expand')} Mode immersif</button></div></section>
  <section class="panorama-space" aria-label="Atelier à gauche, Jarvis au centre et Création à droite">
    <div class="wall-toolbar"><div class="wall-focus" role="group" aria-label="Mettre un écran en avant">${[['all','Vue d’ensemble'],['atelier','01 · Atelier'],['pilotage','02 · Jarvis'],['creation','03 · Création']].map(([id,label])=>`<button data-wall-focus="${id}" aria-pressed="${focus===id}">${label}</button>`).join('')}</div><span class="wall-demo"><i></i> VUE DES TROIS POSTES · PARC SIMULÉ</span></div>
    <div class="wall-monitors" data-focus="${focus}">
      <article class="wall-monitor monitor-production reveal" data-monitor="atelier" style="--order:1">${monitorHeader('atelier','01','ATELIER','MATIÈRE / FABRICATION')}
        <div class="monitor-display production-display"><div class="motion-canvas" data-motion-stage="production" aria-hidden="true"></div><div class="monitor-overline"><span>VUE SPATIALE DU PARC</span><span class="outline-tag">SIMULATION</span></div><div class="production-metric"><strong>${String(count).padStart(2,'0')}</strong><span>RESSOURCES<br>À ORCHESTRER</span></div><div class="scene-caption">RÉSINE UV <span>×</span> FDM</div></div>
        <div class="monitor-machine-strip">${state.machines.map(m=>{const j=current(m.id),progress=j?Math.round(jobProgress(j)):0;return `<button class="mini-machine ${j?.status||'idle'}" data-wall-machine="${m.id}" aria-label="Ouvrir ${m.id}, ${j?.status==='paused'?'simulation en pause':j?.status==='running'?'simulation en cours':'en attente'}"><span>${m.id}</span><i style="--progress:${progress}%"></i><small>${j?progress+'%':'—'}</small></button>`;}).join('')}</div><footer class="monitor-footer"><span><i class="status-dot"></i>${active} simulation${active>1?'s':''} active${active>1?'s':''}</span><button data-action="plan">Répartir ${icon('arrow')}</button></footer>
      </article>
      <article class="wall-monitor monitor-pilotage reveal" data-monitor="pilotage" style="--order:2">${monitorHeader('pilotage','02','JARVIS','LA TOUR DE CONTRÔLE')}
        <div class="monitor-display jarvis-display"><div class="motion-canvas" data-motion-stage="jarvis" aria-hidden="true"></div><div class="monitor-overline"><span>LA CONSOLE DE L’ATELIER</span><span class="outline-tag">VOIX À RACCORDER</span></div><div class="jarvis-display-word"><small>À VOTRE COMMANDE</small><strong>JARVIS</strong></div><div class="wall-jarvis-entry"><form id="wall-command-form"><label for="wall-command-input" class="sr-only">Votre intention pour Jarvis</label><div class="wall-command-field"><input id="wall-command-input" placeholder="Jarvis, orchestre mon projet…" autocomplete="off" maxlength="250"><button type="submit" aria-label="Exécuter cette intention">${icon('arrow')}</button></div></form><div class="quick-intents"><button data-quick-command="Orchestre mon projet">Orchestrer</button><button data-action="wall-model">Aperçu 3D</button><button data-action="connections">Slicer</button></div></div></div>
        ${decision?`<section class="wall-next-decision"><span>PROCHAINE ÉTAPE · ${esc(decision.targetLabel)}</span><h3>${esc(decision.title)}</h3><p>${esc(decision.reason)}</p><button type="button" data-action="${esc(decision.primary?.action||'preparation')}" data-project-id="${esc(project.id)}" ${decision.primary?.pieceId?`data-piece-id="${esc(decision.primary.pieceId)}"`:''}>${esc(decision.primary?.label||'Ouvrir la préparation')} ${icon('arrow')}</button></section>`:''}<div class="wall-receipt" id="wall-command-receipt" role="status">${esc(receipt||'Votre intention devient une mission visible.')}</div><button class="wall-control-entry" data-action="decisions">${icon('spark')} Conseils & Jev ${icon('arrowUp')}</button><div class="monitor-project pilot-stats"><div><strong>${String(state.projects.length).padStart(2,'0')}</strong><span>Dossiers du poste</span></div><div><strong>${archive.length?String(archive.length).padStart(2,'0'):'—'}</strong><span>Références indexées</span></div><button data-action="new-project" aria-label="Créer un nouveau dossier">${icon('plus')}</button></div><footer class="monitor-footer"><span>CONSOLE & ADMINISTRATION</span><button data-action="mission">La mission ${icon('arrow')}</button></footer>
      </article>
      <article class="wall-monitor monitor-creation reveal" data-monitor="creation" style="--order:3">${monitorHeader('creation','03','CRÉATION','L’EMPREINTE BOJ.ART')}
        <div class="monitor-display art-display"><video class="ambient-film" data-ambient-video src="./assets/atelier-motion.mp4" poster="./assets/atelier-motion-poster.webp" muted loop playsinline preload="metadata" aria-label="Montage silencieux d’œuvres et de gestes originaux BOJ.ART"></video><div class="art-display-shade"></div><div class="monitor-overline"><span>ŒUVRES & GESTES D’ORIGINE</span><span class="film-marker">${icon('film')}</span></div><div class="art-display-word"><small>L’ATELIER EN MOUVEMENT</small>LE GESTE.<br><em>L’ŒUVRE.</em></div><button class="ambient-toggle" data-action="ambient" aria-pressed="true" aria-label="Mettre le montage en pause">${icon('pause')}</button><div class="film-progress"><i></i></div></div>
        <div class="monitor-project"><img src="./assets/${esc(project.media||'logo.webp')}" alt="Référence du projet actif"><div><strong>${esc(project.name)}</strong><span>${project.pieces.length} pièces · ${project.height===null?'hauteur à préciser':fmt(project.height||0)+' mm souhaités'}</span></div><button data-action="wall-model" aria-label="Inspecter le modèle 3D">${icon('cube')}</button></div><footer class="monitor-footer"><span>RÉFÉRENCES AUTHENTIQUES</span><button data-action="project-studio">Composer ${icon('arrow')}</button></footer>
      </article>
    </div>
    <div class="wall-captions">${screens.map(([id,num,title,sub])=>`<button class="wall-caption" data-screen="${id}"><span>${num}</span><div><strong>${title}</strong><small>${sub}</small></div>${icon('arrowUp')}</button>`).join('')}</div>
  </section>
  <section class="panorama-bottom reveal" style="--order:4"><div class="wall-active-project"><span class="eyebrow">UNE BASE PARTAGÉE</span><label for="project-picker">Projet actif</label><select id="project-picker">${state.projects.map(p=>`<option value="${esc(p.id)}" ${p.id===project.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><span class="project-sync"><i></i> Les fenêtres de ce navigateur partagent le dossier.</span></div><div class="wall-signature"><img src="./assets/logo.webp" alt="Emblème original BOJ.ART"><div><span>ART. MATIÈRE. MOUVEMENT.</span><button data-action="identity">Explorer la signature ${icon('arrowUp')}</button></div></div></section>
  <div class="immersive-dock"><span>BOJ.ART <i>/</i> LE POSTE</span><button data-action="motion" aria-label="Activer ou réduire les animations">${icon('motion')}</button><button data-action="screens" aria-label="Installer les trois écrans">${icon('screens')}</button><button data-action="immersive" aria-label="Quitter le mode immersif">${icon('close')}</button></div>`;
}
